def copy_exclusive_to_manager(apps, schema_editor):
    """One True flag on any company row means the manager leaves the shared queue."""
    rule = apps.get_model("leads", "CompanyManagerRule")
    mode = apps.get_model("leads", "ManagerQueueMode")
    assignee_ids = rule.objects.filter(exclusive=True).values_list("assignee_id", flat=True).distinct()
    for assignee_id in assignee_ids:
        mode.objects.update_or_create(
            assignee_id=assignee_id,
            defaults={"pinned_only": True},
        )


def copy_manager_back_to_rules(apps, schema_editor):
    """Lossy undo: every rule of a pinned-only manager becomes exclusive.

    The forward step kept one switch per person. Going back cannot tell which
    of that person's rows were exclusive and which were not, so all of them
    are marked exclusive.
    """
    rule = apps.get_model("leads", "CompanyManagerRule")
    mode_model = apps.get_model("leads", "ManagerQueueMode")
    for mode in mode_model.objects.filter(pinned_only=True):
        rule.objects.filter(assignee_id=mode.assignee_id).update(exclusive=True)


